# PowerShell Sync Script for Dream v3.2.0
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8

Write-Host "[1/4] Decoding Dream v3.2.0 payload..." -ForegroundColor Cyan
$b64 = ""
$bytes = [System.Convert]::FromBase64String($b64)
$memStream = New-Object System.IO.MemoryStream(,$bytes)
$gzipStream = New-Object System.IO.Compression.GZipStream($memStream, [System.IO.Compression.CompressionMode]::Decompress)
$reader = New-Object System.IO.StreamReader($gzipStream, [System.Text.Encoding]::UTF8)
$jsonText = $reader.ReadToEnd()
$data = $jsonText | ConvertFrom-Json

Write-Host "[2/4] Writing files with raw UTF-8 (No BOM)..." -ForegroundColor Cyan
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)

foreach ($prop in $data.PSObject.Properties) {
    $relPath = $prop.Name
    $fileContent = $prop.Value
    $fullPath = Join-Path $PSScriptRoot $relPath
    $parentDir = Split-Path $fullPath -Parent

    if (-not (Test-Path $parentDir)) {
        New-Item -ItemType Directory -Path $parentDir -Force | Out-Null
    }

    $contentBytes = $utf8NoBom.GetBytes(($fileContent.Trim() + "`n"))
    [System.IO.File]::WriteAllBytes($fullPath, $contentBytes)
    Write-Host "  -> $relPath" -ForegroundColor Green
}

# Clean up any stray files
$strays = @(
    'apply_desktop_voice_upgrade.py',
    'methods_vision.py',
    'engine.py',
    'echo-vision.py',
    'echo-vision.ts',
    'methods_dialectic.py',
    'sync_repo.py',
    'deploy_v31.py',
    'sync_green.py'
)
foreach ($stray in $strays) {
    $strayPath = Join-Path $PSScriptRoot $stray
    if (Test-Path $strayPath) {
        Remove-Item $strayPath -Force -ErrorAction SilentlyContinue
    }
}

Write-Host "`n[3/4] Staging and committing to Git..." -ForegroundColor Cyan
git add -A
git add --renormalize -A
git commit -m "feat(memory): implement hierarchical episodic memory, temporal KG linking, and desktop temporal studio v3.2.0"

Write-Host "`n[4/4] Pushing to GitHub main..." -ForegroundColor Cyan
git push origin main

Write-Host "`n=======================================================" -ForegroundColor Green
Write-Host " [SUCCESS] Dream v3.2.0 100% synchronized and pushed!" -ForegroundColor Green
Write-Host "=======================================================" -ForegroundColor Green
